'use strict';
window.CobaltUI={
 t(zh,en){return I18n.language==='en'?en:zh;},
 states:{PREPARING:['备货作业中','Preparation in Progress'],DRAFT:['草稿','Draft'],SITE_PENDING:['待现场主管审核','Awaiting Site Review'],PRODUCTION_PENDING:['待生产管理部审核','Awaiting Production Review'],REJECTED:['已驳回','Rejected'],WITHDRAWN:['已撤销','Withdrawn'],RECEIVED:['已正式入库','Received']},
 status(code){return this.t(...(this.states[code]||[code,code]));},
 can(code){return CurrentUser.permissions.includes(code);},
 error(e){const messages={CO_INVALID_INPUT:['输入字段无效','Invalid input fields'],CO_INVALID_COUNTS:['袋数须为1至10000的整数','Bag count must be a whole number from 1 to 10,000'],CO_TOTAL_MISMATCH:['明细袋数与总袋数不一致','Bag quantities do not match the total'],CO_INVALID_BATCH:['历史备货资料无效','Invalid legacy preparation data'],CO_INVALID_WAREHOUSE:['仓库不属于所选项目','Warehouse does not belong to the selected project'],CO_STALE_VERSION:['单据已变化，请刷新后重试','Document changed; refresh and try again'],CO_INVALID_STATE:['当前状态或操作人不允许此操作','This action is not allowed for the current state or actor'],CO_PERMISSION_DENIED:['当前角色无此节点权限','Your role is not authorized for this approval stage'],CO_STATE_CONFLICT:['数据或状态冲突，请刷新核实','Data or state conflict; refresh and verify'],CO_NOT_FOUND:['单据不存在或不在授权范围','Document not found or outside your scope'],CO_PRODUCT_REQUIRED:['请切换至氢氧化钴后操作','Switch to Cobalt Hydroxide first'],CO_KEY_REUSED:['幂等键不能用于不同请求','An idempotency key cannot be reused for different content'],'CO_REASON无效':['请填写原因，最多1000字','Enter a reason, up to 1,000 characters'],'CO_BATCH无效':['历史备货资料无效','Invalid legacy preparation data']};return messages[e.message]?this.t(...messages[e.message]):I18n.translate(e.message,true);},
 page(title,html){Router.page(title,'<div class="co-page" data-no-i18n>'+html+'</div>');for(const table of document.querySelectorAll('.co-page table'))table.dataset.v34Enhanced='true';for(const form of document.querySelectorAll('.co-page form'))form.dataset.v34Reset='true';},
 async route(path){try{if(path==='/preparation/new')await this.create();else if(path==='/preparation')await this.list();else await this.detail(path.split('/')[2]);}catch(e){this.page(this.t('氢氧化钴备货','Cobalt Preparation'),'<p class="error" role="alert">'+esc(this.error(e))+'</p>');}},
 async languageChanged(){const state=document.getElementById('co-create')?this.formValue():null,dirty=ProductContext.dirty;try{if(state)await this.create(state);else await this.route(location.pathname);}finally{ProductContext.dirty=dirty;}},
 async list(){const params=new URLSearchParams(location.search),status=params.get('status')||'',page=Number(params.get('page')||1),d=await API.request('/cobalt/preparations?'+new URLSearchParams({status,page}));this.page(this.t('氢氧化钴备货单','Cobalt Preparation Orders'),`<div class="business-toolbar">${this.can('co:create')?`<a id="co-new" class="button primary" href="/preparation/new">${this.t('新建备货单','Create Preparation')}</a>`:''}<form id="co-filter" class="filters"><label>${this.t('单据状态','Status')}<select name="status"><option value="">${this.t('全部','All')}</option>${Object.keys(this.states).map(s=>`<option value="${s}" ${s===status?'selected':''}>${this.status(s)}</option>`).join('')}</select></label><button class="button secondary">${this.t('查询','Search')}</button></form></div><p>${this.t('备货单不绑定客户或销售合同。生产管理部审核后生成备货作业中库存。','No customer or contract is assigned. Production approval creates physical stock in preparation.')}</p><div class="business-table"><table><thead><tr>${[this.t('备货单号','Order'),this.t('备货批次','Preparation Batch'),this.t('业务日期','Business Date'),this.t('袋数','Bags'),this.t('预计净重（kg）','Expected Net (kg)'),this.t('状态','Status')].map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${d.items.map(p=>`<tr><td><a href="/preparation/${p.id}">${esc(p.document_no)}</a></td><td>${esc(p.preparation_batch_no)}</td><td>${esc(p.business_date)}</td><td>${p.bag_count}</td><td>${Number(p.expected_net_kg).toLocaleString()}</td><td>${this.status(p.status)}</td></tr>`).join('')||`<tr><td colspan="6">${this.t('暂无备货单','No preparation orders')}</td></tr>`}</tbody></table></div><div class="co-pager"><button id="co-prev" class="button secondary" ${page<=1?'disabled':''}>${this.t('上一页','Previous')}</button><span>${page} / ${Math.max(1,Math.ceil(d.total/50))}</span><button id="co-next" class="button secondary" ${page*50>=d.total?'disabled':''}>${this.t('下一页','Next')}</button></div>`);$('co-filter').onsubmit=e=>{e.preventDefault();Router.go('/preparation?'+new URLSearchParams({status:e.target.elements.status.value}));};for(const [id,delta] of [['co-prev',-1],['co-next',1]])$(id).onclick=()=>Router.go('/preparation?'+new URLSearchParams({status,page:page+delta}));ProductContext.dirty=false;},
 formValue(){return CoRefinement.formValue();},
 create(saved){return CoRefinement.create(saved);},
 async detail(id){const page=Number(new URLSearchParams(location.search).get('bag_page')||1),d=await API.request('/cobalt/preparations/'+id+'?bag_page='+page);const review=d.status==='SITE_PENDING'&&['site_supervisor','admin'].includes(CurrentUser.role_code)&&this.can('co:site-review')?'site-approve':d.status==='PRODUCTION_PENDING'&&['production_manager','admin'].includes(CurrentUser.role_code)&&this.can('co:production-review')?'production-approve':null,own=d.created_by===CurrentUser.id;
 const actions=[];if(own&&this.can('co:submit')&&['DRAFT','REJECTED'].includes(d.status))actions.push(['submit',this.t('提交现场审核','Submit for Site Review')]);if(review){actions.push([review,this.t('审核通过','Approve')],['reject',this.t('驳回','Reject')]);}if(own&&this.can('co:withdraw')&&['DRAFT','REJECTED','SITE_PENDING'].includes(d.status))actions.push(['withdraw',this.t('撤销备货单','Withdraw')]);
 this.page(this.t('氢氧化钴备货详情','Cobalt Preparation Details'),`<div class="co-document"><strong>${esc(d.preparation_batch_no||d.document_no)}</strong><span class="title-chip" id="co-status">${this.status(d.status)}</span></div><dl><dt>${this.t('备货批次','Preparation Batch')}</dt><dd>${esc(d.preparation_batch_no)}</dd><dt>${this.t('创建业务日期（卢本巴希）','Creation Business Date (Lubumbashi)')}</dt><dd>${esc(d.business_date)}</dd><dt>${this.t('袋数 / 预计净重','Bags / Expected Net Weight')}</dt><dd>${d.bag_count} / ${(d.bag_count*647).toLocaleString()} kg</dd></dl><ol class="co-steps">${[this.t('物流操作员提交','Logistics Submission'),this.t('现场主管审核','Site Supervisor Review'),this.t('生产管理部审核并入库','Production Review and Receipt')].map((s,i)=>`<li class="${(i===0&&d.submitted_at||i===1&&d.site_reviewed_at||i===2&&d.production_reviewed_at)?'co-step-done':''}">${s}</li>`).join('')}</ol><div class="co-inventory"><strong id="co-physical">${this.t('实物库存','Physical Stock')}: ${d.inventory.physical_bags} ${this.t('袋','bags')}</strong><span>${this.t('可装车库存','Loadable Stock')}: 0</span><span>${d.status==='RECEIVED'?(AppConfig.cobaltWorkV39?CobaltWorkUI.status(d.work?.status||'PREPARING'):this.t('库存状态：备货作业中','Inventory status: Preparation in Progress')):this.t('尚未正式入库','Not yet received')}</span></div><div class="business-toolbar">${actions.map(([a,n])=>`<button data-co-action="${a}" class="button ${a==='reject'||a==='withdraw'?'secondary':'primary'}">${n}</button>`).join('')}${AppConfig.cobaltWorkV39&&d.status==='RECEIVED'?`<a id="co-work-open" class="button primary" href="/preparation/${d.id}/work">${this.t('备货作业','Preparation Work')}</a><span class="title-chip">${CobaltWorkUI.status(d.work?.status||'PREPARING')}</span>`:''}<a class="button secondary" href="/preparation">${this.t('返回列表','Back to List')}</a></div><p id="co-error" class="error" role="alert"></p><h2>${this.t('袋号与预计重量','Bag Numbers and Expected Weights')}</h2><div class="business-table"><table id="co-bags"><thead><tr>${[this.t('袋号','Bag Number'),this.t('预计毛重（kg）','Expected Gross (kg)'),this.t('包装（kg）','Packaging (kg)'),this.t('预计净重（kg）','Expected Net (kg)')].map(s=>'<th>'+s+'</th>').join('')}</tr></thead><tbody>${d.bags.map(b=>`<tr><td>${esc(b.bag_no)}</td><td>${+b.expected_gross_kg}</td><td>${+b.packaging_kg}</td><td>${+b.expected_net_kg}</td></tr>`).join('')}</tbody></table></div><div class="co-pager"><button id="co-bag-prev" class="button secondary" ${page<=1?'disabled':''}>${this.t('上一页','Previous')}</button><span>${page} / ${Math.ceil(d.bag_count/200)}</span><button id="co-bag-next" class="button secondary" ${page*200>=d.bag_count?'disabled':''}>${this.t('下一页','Next')}</button></div><h2>${this.t('审批历史','Approval History')}</h2><div class="business-table"><table id="co-history"><thead><tr><th>${this.t('时间','Time')}</th><th>${this.t('操作人','Actor')}</th><th>${this.t('状态','Status')}</th><th>${this.t('原因','Reason')}</th></tr></thead><tbody>${d.events.map(e=>`<tr><td>${esc(BusinessTime.display(e.occurred_at))}</td><td>${esc(I18n.language==='en'?(e.actor_name_en||EmployeeIdentity.name({display_name:e.actor_name})):e.actor_name)}</td><td>${this.status(e.to_status)}</td><td>${esc(e.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`);
 for(const button of document.querySelectorAll('[data-co-action]'))button.onclick=async()=>{const action=button.dataset.coAction;let reason='';const needsReason=['reject','withdraw'].includes(action);if(!await OperationConfirm.ask({title:button.textContent,rows:[[this.t('备货单','Preparation'),d.document_no]],comment:needsReason,commentRequired:needsReason,commentLabel:this.t('原因（必填）','Reason (required)'),onComment:value=>reason=value}))return;button.disabled=true;try{await API.request('/cobalt/preparations/'+id+'/'+action,{method:'POST',body:{version:d.version,...(needsReason?{reason}:{})}});ProductContext.dirty=false;await this.detail(id);}catch(e){$('co-error').textContent=this.error(e);button.disabled=false;}};
 for(const [button,delta] of [['co-bag-prev',-1],['co-bag-next',1]])$(button).onclick=()=>Router.go('/preparation/'+id+'?bag_page='+(page+delta));ProductContext.dirty=false;
 }
};
Object.assign(Accounts.permissionLabels,{'co:read':'氢氧化钴备货查看','co:create':'氢氧化钴备货创建','co:submit':'氢氧化钴备货提交','co:site-review':'氢氧化钴现场审核','co:production-review':'氢氧化钴生产审核','co:withdraw':'氢氧化钴备货撤销'});
Accounts.groups.co='氢氧化钴备货与入库';
Object.assign(TRANSLATIONS.en,{'氢氧化钴备货查看':'View Cobalt Preparations','氢氧化钴备货创建':'Create Cobalt Preparations','氢氧化钴备货提交':'Submit Cobalt Preparations','氢氧化钴现场审核':'Cobalt Site Review','氢氧化钴生产审核':'Cobalt Production Review','氢氧化钴备货撤销':'Withdraw Cobalt Preparations','氢氧化钴备货与入库':'Cobalt Preparation and Receipt','已确认钴业务操作结果':'Cobalt operation confirmed','结果尚未确认，请保留原幂等键':'Result unknown; retain the original idempotency key'});
I18n.pattern=new RegExp(Object.keys(TRANSLATIONS.en).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
